<span class="line"><span style="color:#E5C07B;">IEnumerator</span><span style="color:#ABB2BF;">&lt;</span><span style="color:#C678DD;">object</span><span style="color:#ABB2BF;">&gt; </span><span style="color:#E06C75;">enumerator</span><span style="color:#56B6C2;"> =</span><span style="color:#E5C07B;"> objects</span><span style="color:#ABB2BF;">.</span><span style="color:#61AFEF;">GetEnumerator</span><span style="color:#ABB2BF;">();</span></span>
