<span class="line"><span style="color:#E5C07B;">demo</span><span style="color:#ABB2BF;">.</span><span style="color:#61AFEF;">Handle</span><span style="color:#ABB2BF;">(</span><span style="color:#E06C75;">actStr</span><span style="color:#ABB2BF;">);</span></span>
